def convert_list_to_dict(lst):
    """
    Convert a list of strings to a dictionary with values as list of strings.

    Args:
    lst (list): A list of strings

    Returns:
    dict: A dictionary with parsed list of strings
    """
    dict_ = {}
    for str_ in lst:
        if str_[0] not in dict_:
            dict_[str_[0]] = [str_]
        else:
            dict_[str_[0]].append(str_)
    return dict_

